function QuestLvl1:__init()
    self.controller = nil

    -- 每个 task 存储唯一的 函数指针; 多个 key 允许指向同一个 函数指针
    -- 不允许在同一个 task 阶段, 存在两个激活的 gear (及其对应的 函数指针)
    -- 如果发现某个 task 没有绑定值, 则执行默认流程;
    -- ---
    -- 之所以不用 List 是因为现在不用担心 RunAfterQuestBaseStart() 和 Gear.Start() 的执行顺序问题了;
    self.switchTaskFuncs = {}       -- Dictionary<int,ToNextFuncType>
    self.handleLastTaskFuncs = {}   -- Dictionary<int,ToNextFuncType>
end


function QuestLvl1:__delete()
    self.co_1 = nil

    if self.co_6 ~= nil then
        cs_coroutine.stop(self.co_6)
    end
    self.co_6 = nil
end



--@param piecesCollection_ PiecesCollection
function QuestLvl1:SelfInit( levelID_, piecesCollection_ )
    KTool.SetActive(self.controller.gameObject, true);

    assert( self.ui_taskPanelBH and self.piecesCollectionBH and self.firstGear )
    
    self.ui_taskPanel          = DreamSpaceLuaUtils.GetLuaScr(self.ui_taskPanelBH.gameObject,          "Game.DreamSpace.Level1.UI.UIMain_TaskPanel" )
    self.ui_promptDialog       = DreamSpaceLuaUtils.GetLuaScr(self.ui_promptDialogBH.gameObject,       "Game.DreamSpace.Level1.UI.UIMain_PromptDialog" )
    self.piecesCollection      = DreamSpaceLuaUtils.GetLuaScr(self.piecesCollectionBH.gameObject,      "Game.DreamSpace.PiecesCollection.PiecesCollection" )
    self.floatingMarkerManager = DreamSpaceLuaUtils.GetLuaScr(self.floatingMarkerManagerBH.gameObject, "Game.DreamSpace.Hint.FloatingMarkerManager" )

    assert( self.ui_taskPanel and self.piecesCollection )

    assert( self.endStoryBH )
    self.endStory = DreamSpaceLuaUtils.GetLuaScr(self.endStoryBH.gameObject, "Game.DreamSpace.Level1.Story.DreamSpace_EndStory" )
    assert( self.endStory )


    --self.questReward = QuestReward.New() -- new 奖励信息

    -- core
    self.core = QuestCore.New( levelID_ )

    self.piecesCollection = piecesCollection_


    self:ReadQuestVO()

    self.core:DebugPrint()


    -- 绑定函数指针...
    self.core.OnSwitchTaskFunc = function(taskSwitchData_)
        self:OnSwitchTask(taskSwitchData_)
    end

    self.core.OnHandleLastTaskFunc = function(taskSwitchData_)
        self:OnHandleLastTask(taskSwitchData_)
    end


    -------------------------------------------------------
    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.co_0 = cs_coroutine.start(self.DelayInit, self)
end



function QuestLvl1:DelayInit()

    self.core.isInit = true
end



function QuestLvl1:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    DreamSpaceLuaUtils.StopCoroutine( self.co_6 )
    self.co_0 = nil
    self.co_6 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


function QuestLvl1:ReadQuestVO()

    local questVO = DreamlandUtils.GetDreamlandQuestVo( self.core.questID ) -- 梦境空间关卡表
    self.core.questTitle = questVO.levelName
    self.core.questDescription = questVO.levelDesc

    -- 手动读取另一张表..
    local questTableFile = settingMgr:Get(AutoIds.IdSetting3082)  -- TableFile,  任务信息表 
    local length = questTableFile:GetRowCount()
    for i=1,length do -- (实际从表格第 5 行开始读)

        local row = questTableFile:GetRow(i) -- TableFileRow
        
        local levelID = tonumber(row:Get("levelId"))
        if levelID == self.core.questID then 
            -- 仅处理 本 quest 相关的

            local taskIDStr = row:Get("taskID")
            local taskDescriptionStr = ParseUtils.ParseLocalizeText(row, "taskDescription")
            if taskIDStr=="" or taskDescriptionStr=="" then 
                printError("koko 配表数据异常")
            else 
                self.core:AddTask( Task.New( taskIDStr, taskDescriptionStr ) )
            end
        end
    end
end




---@return void
---@param taskRange_ TaskRange
---@param func_ QuestSystem.ToNextFuncType
function QuestLvl1:RegistSwitchTaskFunc(taskRange_, func_)
    if taskRange_.isInit ~= true then 
        printError("koko taskRange_.isInit ~= true")
        return
    end 
    ---
    for i = taskRange_.lowestTaskIdx, taskRange_.highestTaskIdx do
        if self.switchTaskFuncs[i] == nil then 
            self.switchTaskFuncs[i] = func_
        else 
            printError("koko 不能向同一个 task 注册多个 callback... task id = " .. i)
        end 
    end
end


---@return void
---@param taskRange_ TaskRange
---@param func_ QuestSystem.ToNextFuncType
function QuestLvl1:RejistHandleLastTaskFunc(taskRange_, func_)
    if taskRange_.isInit ~= true then 
        printError("koko taskRange_.isInit ~= true")
        return
    end 
    for i = taskRange_.lowestTaskIdx, taskRange_.highestTaskIdx do
        assert( self.handleLastTaskFuncs[i] == nil, "不能向同一个 task 注册多个 callback... task id = " .. i)
        self.handleLastTaskFuncs[i] = func_
    end
end



-- 拙劣地实现 调用 基类默认版虚函数
---@return System.Collections.IEnumerator
---@param taskRange_ TaskRange
function QuestLvl1:ToNextTask(taskRange_)
    cs_coroutine.yield_return( self.core:ToNextTask(taskRange_) )
end



