function QuestLvl1:RunFirstTask()
end




-- ======================================================== --
---@return System.Collections.IEnumerator
---@param taskSwitchData_ TaskSwitchData
function QuestLvl1:OnSwitchTask(taskSwitchData_)
    -- 派生类自定义段
    if self.switchTaskFuncs[taskSwitchData_.oldTaskIdx] ~= nil then
        -- 使用 Gear 自定义的流程:
        return self.switchTaskFuncs[taskSwitchData_.oldTaskIdx](taskSwitchData_)
    else 
        -- 本 demo 中要求所有 gear 手动实现
        --assert(false)
        printError("koko 要求所有 gear 手动实现")
    end
end



-- ======================================================== --
---@return System.Collections.IEnumerator
---@param taskSwitchData_ TaskSwitchData
function QuestLvl1:OnHandleLastTask(taskSwitchData_)
    if self.handleLastTaskFuncs[taskSwitchData_.oldTaskIdx] ~= nil then
        -- ===== 使用 Gear 自定义的流程 =====:
        cs_coroutine.yield_return( self.handleLastTaskFuncs[taskSwitchData_.oldTaskIdx](taskSwitchData_) )

    else 
        -- ===== 默认流程: =====:
        self.core:CallBeforeQuestFinish()
        
        DreamSpaceLuaUtils.StopCoroutine( self.co_6 )
        self.co_6 = cs_coroutine.start(function()  


            -- 正式播放 end 剧情
            cs_coroutine.yield_return( self.endStory:Play_2() )

            ---
            local RoleControllerRootCanvasMgr = import('Game.DreamSpace.UI.RoleControllerRootCanvasMgr'):GetInstance()
            RoleControllerRootCanvasMgr:CheckOrInitSync()
            RoleControllerRootCanvasMgr:ShowOrHide( false  ) -- hide
            
            
            -- 解除 鼠标锚点锁定:  (要回到 主游戏 界面了)
            Cursor.lockState = CursorLockMode.None

            DreamSpaceStates.IsSubPanelFreeInPC_Reset() -- PC 版 禁止打开 ui 子界面 
            
            --碎片数据:
            local piecesDatas = self.piecesCollection:GetCollectedPiecesDatas()  -- int[]

            DreamSpaceStates.isAllPiecesCollectedThisTime = self.piecesCollection:IsAllPiecesCollected()

            -- 恢复暂帧率:
            if type(DreamSpaceStates.cachedFrameRate) == "number" and DreamSpaceStates.cachedFrameRate >= 30 then 
                Application.targetFrameRate = DreamSpaceStates.cachedFrameRate
            else
                printError("koko 暂存的白塔外部帧率丢失 " .. tostring(DreamSpaceStates.cachedFrameRate) )
                Application.targetFrameRate = 30
            end
            
            -- 本次游戏完成了几个 task: 
            local taskNum = checkInt( DreamSpaceStates.FinshedTaskNum )
            print("koko - 通关, 本次白塔 完成 " .. tostring(taskNum) .. " 个 task;" )

            local DreamlandComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DreamlandComponent)

            if checkNumber(DreamSpaceStates.questId) == 0 then 
                printError("koko 异常, questId 异常 = " .. tostring(DreamSpaceStates.questId) )
                return
            end 

            -- 设置 loading 界面的 bg图:
            local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
            KCookie.Set(Constants.UICacheDataKeys.OP_LOADING_IMG_ID, DreamSpaceStates.LoadingPanel_IMG_ID) 

            DreamlandComponent:OverseaBoxQuestGradeReq(
                {
                    questId = DreamSpaceStates.questId,
                    piece = piecesDatas,
                    isPassed = 1,           -- 正式通关关卡
                    taskNum = taskNum
                },
                -- collectionIds 是将 piecesDatas 序列化为一个 string;
                function(rewards, collectionIds)    
                    UIModule.OpenDialog(
                        { 
                            id = Constants.UITypeIds.UIActionDreamlandBattleEndNode, 
                            parameters = {id = DreamSpaceStates.questId, rewards = rewards, collectionIds = collectionIds}
                        }, 
                        { {id = Constants.UITypeIds.UIActionPrimaryMapDialog } }
                    )
                end
            )

        end)


    end
end



return QuestLvl1
